/* Tamil strings for the phase 2 Ganita lessons: N1 lakh and crore, N3 equal parts, U1 rupees and paise. Draft translation: needs review by a native-speaker teacher. */
window.Sutra.i18n.add('ta', {
  'bench.toMistake': 'தவறைக் கண்டுபிடி',

  /* N1 */
  'prashna.N1.q': 'ஒரு அரங்கம் 1,00,000 பேரை உள்ளடக்கும். அது மில்லியனை விட அதிகமா, குறைவா, அல்லது சமமா?',
  'prashna.N1.c1': 'மில்லியனை விட அதிகம்', 'prashna.N1.c2': 'மில்லியனை விட குறைவு', 'prashna.N1.c3': 'சமம்',
  'prashna.N1.a': 'குறைவு. 1,00,000 ஒரு லட்சம். மில்லியன் பத்து லட்சம்: 10,00,000.',
  'bodha.N1.what': 'எவ்வளவு பெரிய எண்ணாக இருந்தாலும், அதே பத்து இலக்கங்களால் எழுதப்படும். இலக்கம் நிற்கும் [[place|இடம்]] அதன் மதிப்பைத் தரும்.',
  'bodha.N1.can': 'கோடி வரை எண்களை இந்திய முறையிலும், சர்வதேச முறையிலும் படிக்கவும் எழுதவும் முடியும்.',
  'bodha.N1.idea': 'ஒவ்வொரு வீட்டிலும் 9 மணிகள் வரை. ஒரு வீட்டில் 10 ஆனால், அடுத்த இடது வீட்டில் 1 மணியாகக் கட்டப்படும்.',
  'bodha.N1.why': 'ஒவ்வொரு இடமும் வலதில் உள்ள இடத்தின் பத்து மடங்கு. காற்புள்ளிகள் இடங்களைக் குழுவாக்கி படிக்க உதவும். இந்தியாவில் கடைசி மூன்று இலக்குகள், பிறகு [[period|இரட்டைகள்]]: ஆயிரம், லட்சம், கோடி.',
  'bodha.N1.example': '12,34,567 படி.',
  'bodha.N1.example1': '12 லட்சம் இடத்தில்: பன்னிரண்டு லட்சம்.',
  'bodha.N1.example2': '34 ஆயிரம் இடத்தில்: முப்பத்து நான்கு ஆயிரம்.',
  'bodha.N1.example3': '567 ஐநூற்று அறுபத்து ஏழு. சேர்த்தால்: பன்னிரண்டு லட்சம், முப்பத்து நான்கு ஆயிரம், ஐநூற்று அறுபத்து ஏழு.',
  'bodha.N1.where': 'இந்தியாவில் சுமார் 140 கோடி மக்கள். வீடுகளின் விலை லட்சங்களில். வேறு நாடுகள் ஒரு லட்சத்தை 100,000, பத்து லட்சத்தை ஒரு மில்லியன் என்று எழுதும்.',
  'bodha.N1.sutra': 'ஒவ்வொரு இடமும் வலதில் உள்ள இடத்தின் பத்து மடங்கு.',
  'gloss.place': 'எண்ணில் இலக்கம் நிற்கும் இடம்: ஒன்றுகள், பத்துகள், நூறுகள் முதலியன.',
  'gloss.period': 'ஒன்றாகப் படிக்கப்படும் இடக் குழு, ஆயிரம் அல்லது லட்சம் போல.',
  'pv.ones': 'ஒன்றுகள்', 'pv.tens': 'பத்துகள்', 'pv.hundreds': 'நூறுகள்', 'pv.thousands': 'ஆயிரங்கள்', 'pv.tenThousands': 'பத்தாயிரம்',
  'pv.lakhs': 'லட்சங்கள்', 'pv.tenLakhs': 'பத்து லட்சம்', 'pv.crores': 'கோடிகள்',
  'pv.short.ones': 'ஒ', 'pv.short.tens': 'ப', 'pv.short.hundreds': 'நூ', 'pv.short.thousands': 'ஆ', 'pv.short.tenThousands': 'ப.ஆ',
  'pv.short.lakhs': 'இ', 'pv.short.tenLakhs': 'ப.இ', 'pv.short.crores': 'கோ',
  'pv.addBead': '{place} வீட்டில் ஒரு மணி சேர்',
  'place.title': 'இடமதிப்பு வீடுகள்',
  'place.indian': 'இந்திய முறை',
  'place.intl': 'சர்வதேச முறை',
  'place.s1': 'பார்: வீடுகள் 99,999 காட்டுகின்றன. இன்னும் ஒரு மணி சேர்த்து ஒவ்வொரு வீடும் கட்டப்படுவதைப் பார்.',
  'place.addOne': 'ஒரு மணி சேர்',
  'place.s1done': 'பத்து ஒன்றுகள் ஒரு பத்து, பத்து பத்துகள் நூறு… இறுதியில் ஒரு லட்சம்: 1,00,000.',
  'place.s2': 'உன் முறை: 3,05,200 கட்டு. மணி சேர்க்க ஒரு வீட்டைத் தொடு.',
  'place.s2done': 'அது 3,05,200: மூன்று லட்சம், ஐயாயிரம், இரண்டு நூறு.',
  'place.s3': 'இப்போது: 4,50,000 சர்வதேச முறையில் எப்படி எழுதப்படும்?',
  'place.s3done': 'அதே எண், வேறு காற்புள்ளிகள்: இந்தியா 4,50,000, சர்வதேசம் 450,000.',
  'place.s3try': 'வலதிலிருந்து முதல் காற்புள்ளிக்கு மூன்று இலக்கு; பிறகு தொடர்ந்து மூன்று மூன்று.',
  'mistake.N1.intro': 'ஆஷா “இரண்டு லட்சம் ஐயாயிரம்” என்று எண்களில் எழுதினாள். ஒரு படி தவறு. எது?',
  'mistake.N1.s1': 'இரண்டு லட்சம் என்றால் லட்சம் வீட்டில் 2.',
  'mistake.N1.s2': 'ஐயாயிரம் என்றால் ஆயிரம் வீட்டில் 5.',
  'mistake.N1.s3': 'ஆக 2-ஐ எழுதி அடுத்து 5000: 2,5000.',
  'mistake.N1.s4': 'மற்ற வீடுகளில் மணிகள் இல்லை.',
  'mistake.N1.fine1': 'சரி: லட்சம் வீட்டில் 2.',
  'mistake.N1.fine2': 'இதுவும் சரி: ஆயிரம் வீட்டில் 5.',
  'mistake.N1.fine4': 'உண்மை: பத்தாயிரம், நூறு, பத்து, ஒன்று காலியாக — 0 வேண்டும். முன்னால் பார்.',
  'mistake.N1.found': 'இங்கே. ஆஷா இலக்கங்களை அருகில் எழுதினாள், வீடுகளில் வைக்கவில்லை. காலி வீடுகளுக்கு 0: 2,05,000.',
  'explain.N1.s': 'ஒவ்வொரு இடமும் வலதில் உள்ள இடத்தின் {0} மடங்கு. இந்தியாவில் ஆயிரத்துக்குப் பிறகு ஒவ்வொரு {1} இலக்குக்கும் காற்புள்ளி.',
  'explain.N1.two': 'இரண்டு', 'explain.N1.ten': 'பத்து', 'explain.N1.hundred': 'நூறு',
  'explain.N1.one': 'ஒன்று', 'explain.N1.three': 'மூன்று',
  'explain.N1.hint': 'வீடுகளைப் பார்: எத்தனை மணிகள் ஒன்றாகக் கட்டப்படுகின்றன? லட்சம் எப்படி குழுவாக்கப்படுகிறது?',
  'know.N1': 'ஒவ்வொரு இடமும் வலதில் உள்ள இடத்தின் பத்து மடங்கு; லட்சம், கோடி இந்திய முறையிலும் சர்வதேச முறையிலும் படிக்கலாம்.',

  /* N3 */
  'prashna.N3.q': 'ரவி 1/2 ரொட்டி சாப்பிடுகிறான். அதே அளவு ரொட்டியில் மினி 2/4. யார் அதிகம் சாப்பிட்டார்கள்?',
  'prashna.N3.c1': 'ரவி', 'prashna.N3.c2': 'மினி', 'prashna.N3.c3': 'இருவரும் சமம்',
  'prashna.N3.a': 'சமம். இரண்டு கால் பாகங்கள், ஒரு அரை பாகத்தைப் போலவே ரொட்டியின் அதே பகுதியை மூடும்.',
  'frac.ravi': 'ரவி: 1/2', 'frac.mini': 'மினி: 2/4',
  'bodha.N3.what': '[[fraction|பின்னம்]] சம பகுதிகளாக வெட்டப்பட்ட முழு மொத்தத்தின் ஒரு பகுதியைச் சொல்லும்.',
  'bodha.N3.can': 'பின்னங்களைப் படிக்கவும், சமமான பின்னங்களைக் கண்டுபிடிக்கவும், ஒப்பிடவும் முடியும்.',
  'bodha.N3.idea': 'பட்டையை 4 சம பகுதிகளாக வெட்டி 3-ஐ நிழலிடு. அது 3/4. கீழ் எண் [[denominator|பகுதிகளின் எண்ணிக்கை]]. மேல் எண் நீ எடுக்கும் பகுதிகள்.',
  'bodha.N3.why': 'பகுதிகள் சமமாக இருக்க வேண்டும். ஒரு பகுதி பெரியதாக இருந்தால் “நான்கில் ஒன்று” என்பது வேறு அளவாகிறது; பின்னம் உண்மையைச் சொல்லாது.',
  'bodha.N3.example': 'பட்டையை அரையாக மடி, மீண்டும் மடி.',
  'bodha.N3.example1': 'ஒரு மடிப்பு: 2 சம பகுதி. ஒன்றை நிழலிடு: 1/2.',
  'bodha.N3.example2': 'மீண்டும் மடி: ஒவ்வொரு அரையும் 2 கால் பாகம். அதே நிழல் இப்போது 2/4.',
  'bodha.N3.example3': 'இன்னும் ஒரு மடிப்பு: 4/8. நிழலிட்ட அளவு மாறவில்லை: 1/2 = 2/4 = 4/8.',
  'bodha.N3.where': 'அரை லிட்டர் பால், கால் கிலோ தக்காளி, அரை மணி நேரம். பகுதிகள் அதிகமானால் ஒவ்வொன்றும் சிறியது: 1/4 < 1/2.',
  'bodha.N3.sutra': 'முழுவைச் சம பகுதிகளாக வெட்டு: கீழ் எண் பகுதிகள், மேல் எண் நீ எடுப்பவை.',
  'gloss.fraction': 'முழுவின் பகுதிக்கான எண், 1/2 அல்லது 3/4 போல.',
  'gloss.denominator': 'பின்னத்தின் கீழ் எண்: முழு எத்தனை சம பகுதிகளாக வெட்டப்பட்டது.',
  'frac.unequal': 'சம பகுதிகள் அல்ல: இது இரண்டு அரைகள் அல்ல.',
  'frac.part': '{d}-ல் {n}வது பகுதி',
  'frac.title': 'பட்டை மடித்தல்',
  'frac.s1': 'பார்: ஒரு பட்டையை அரையாக மடித்து ஒரு பகுதி நிழலிடு. மற்றதை அரை, மீண்டும் அரை.',
  'frac.fold': 'பட்டைகளை மடி',
  'frac.s1done': 'அரையும் இரண்டு கால் பாகமும் சரியாகப் பொருந்தும்: 1/2 = 2/4.',
  'frac.s2': 'உன் முறை: மேல் பட்டையில் 3/4 நிழலிடு, அதே அளவை எண்ணெட்டில் நிழலிடு. பகுதியைத் தொட்டு அதுவரை நிழலிடு.',
  'frac.s2done': 'மூன்று கால் பாகம் ஆறு எண்ணெட்டு: 3/4 = 6/8. ஒவ்வொரு கால் பாகமும் இரண்டு எண்ணெட்டாக மடிந்தது.',
  'frac.s3': '2/3, 3/4 — எது பெரியது?',
  'frac.same': 'சமம்',
  'frac.s3done': '3/4 பட்டையில் 2/3-ஐ விட வரை: 3/4 பெரியது.',
  'frac.s3try': 'ஒவ்வொரு நிழலும் பட்டையில் எங்கு முடிகிறது என்று பார்.',
  'mistake.N3.intro': 'கிரண் அதே ரொட்டியில் 1/3, 1/2 ஒப்பிட்டான். ஒரு படி தவறு. எது?',
  'mistake.N3.s1': 'இரண்டு பின்னங்களும் அதே ரொட்டியின் பகுதிகள்.',
  'mistake.N3.s2': '1/3 என்றால் 3 சம பகுதி, ஒன்றை எடுத்தல்.',
  'mistake.N3.s3': '3, 2-ஐ விட பெரியது, அதனால் 1/3 > 1/2.',
  'mistake.N3.s4': 'ஆக ரொட்டியின் மூன்றில் ஒரு பங்கு அரையை விட அதிகம்.',
  'mistake.N3.fine1': 'சரி: ஒப்பிடுவது அதே முழுவுக்கு மட்டுமே.',
  'mistake.N3.fine2': 'சரி: மூன்று சம பகுதி, ஒன்று எடுத்தல்.',
  'mistake.N3.fine4': 'இந்த வரி முந்தையதை மட்டும் சொல்கிறது. முன்னால் பார்.',
  'mistake.N3.found': 'இங்கே. பகுதிகள் அதிகமானால் ஒவ்வொன்றும் சிறியது. 3 பகுதியில் ஒன்று அரையை விட சிறியது: 1/3 < 1/2.',
  'explain.N3.s': 'கீழ் எண் முழு எத்தனை {0} பகுதிகளாக வெட்டப்பட்டது என்று சொல்லும். ஒவ்வொரு பகுதியையும் இரண்டாக மடிக்கும்போது பின்னம் வேறு தோற்றம், அளவு {1}.',
  'explain.N3.equal': 'சம', 'explain.N3.big': 'பெரிய', 'explain.N3.any': 'வேறு',
  'explain.N3.bigger': 'பெரிய', 'explain.N3.same': 'அதே', 'explain.N3.smaller': 'சிறிய',
  'explain.N3.hint': 'பட்டைகளைப் பார்: பகுதிகள் சம அளவா? மடிக்கும்போது நிழல் வளர்ந்ததா?',
  'know.N3': 'பின்னம் ஒரு முழுவின் சம பகுதிகளை எண்ணும்; ஒவ்வொரு பகுதியையும் இரண்டாக மடித்தால் சம பின்னம், 3/4 = 6/8.',

  /* U1 */
  'prashna.U1.q': 'ஒரு பென்சில் ₹4.5, ஒரு ரப்பர் ₹4.25. எது விலை அதிகம்?',
  'prashna.U1.c1': 'பென்சில்', 'prashna.U1.c2': 'ரப்பர்', 'prashna.U1.c3': 'இரண்டும் சமம்',
  'prashna.U1.a': 'பென்சில். ₹4.5 = ₹4.50: 50 பைசா, 25 பைசாவை விட அதிகம்.',
  'money.pencil': 'பென்சில்', 'money.eraser': 'ரப்பர்',
  'bodha.U1.what': '₹3.75-ல் புள்ளி, [[decimal|தசமப் புள்ளி]], முழு ரூபாயை ரூபாயின் பகுதியிலிருந்து பிரிக்கிறது.',
  'bodha.U1.can': 'ரூபாய், பைசா படித்தல், மாற்றம், ஒப்பீடு செய்ய முடியும்.',
  'bodha.U1.idea': 'ஒரு ரூபாயை 100 சிறு சதுரங்களாக நினை. ஒவ்வொன்றும் 1 பைசா. 10 சதுர வரிசை 10 பைசா, ரூபாயின் பத்தில் ஒன்று.',
  'bodha.U1.why': 'புள்ளிக்குப் பிறகும் இடமதிப்பு தொடரும். முதல் இடம் பத்தில் ஒன்று, இரண்டாம் [[hundredth|நூறில் ஒன்று]]: ஒவ்வொரு இடமும் இடதில் உள்ளதின் பத்தில் ஒன்று.',
  'bodha.U1.example': '₹3.75 என்றால் என்ன?',
  'bodha.U1.example1': '3 முழு ரூபாய்.',
  'bodha.U1.example2': '7 பத்தில் ஒன்று: 10 பைசா வரிசை 7 = 70 பைசா.',
  'bodha.U1.example3': '5 நூறில் ஒன்று: இன்னும் 5 பைசா. மொத்தம் 300 + 70 + 5 = 375 பைசா.',
  'bodha.U1.where': 'கடை பில், பெட்ரோல் விலை, கிரிக்கெட் ரன் விகிதம். ₹0.5 = ₹0.50 = 50 பைசா. புள்ளிக்குப் பிறகு நீளமான எண் எப்போதும் பெரியது அல்ல.',
  'bodha.U1.sutra': 'புள்ளிக்குப் பிறகு ஒவ்வொரு இடமும் இடதில் உள்ளதின் பத்தில் ஒன்று.',
  'gloss.decimal': 'முழு எண்ணைப் பகுதியிலிருந்து பிரிக்கும் புள்ளி.',
  'gloss.hundredth': 'முழுவின் 100 சம பகுதிகளில் ஒன்று: 1 பைசா ரூபாயின் நூறில் ஒன்று.',
  'money.paise': 'பைசா',
  'money.title': 'ரூபாய் கட்டம்',
  'money.chart': 'ரூபாய் . பத்தில் ஒன்று நூறில் ஒன்று',
  'money.s1': 'பார்: ₹1.25 — ஒரு ரூபாய், இரண்டு 10 பைசா பட்டை, ஐந்து பைசா.',
  'money.showMe': '₹1.25 கட்டு',
  'money.s1done': '₹1.25 = 1 ரூபாய், 2 பத்தில் ஒன்று, 5 நூறில் ஒன்று: 125 பைசா.',
  'money.s2': 'உன் முறை: ₹2.50 கட்டு.',
  'money.addRupee': '+ ₹1',
  'money.addStrip': '+ 10 பைசா',
  'money.addSquare': '+ 1 பைசா',
  'money.s2done': '₹2.50 = 2 ரூபாய், 5 பட்டை: 250 பைசா. ₹2.5 என்றும் எழுதலாம்.',
  'money.s3': 'எது அதிகம்: ₹0.5 அல்லது ₹0.45?',
  'money.s3done': 'இடம் வாரியாக ஒப்பிடு: 5 பத்தில் ஒன்றுகள் > 4 பத்தில் ஒன்றுகள், எனவே ₹0.5 அதிகம். ₹0.5 = 50 பைசா.',
  'money.s3try': 'புள்ளிக்குப் பிறகு முதல் இடம்: எத்தனை 10 பைசா பட்டை?',
  'mistake.U1.intro': 'நேகா இரண்டு மிட்டாய் விலைகளை ஒப்பிட்டாள்: ₹0.5, ₹0.45. ஒரு படி தவறு. எது?',
  'mistake.U1.s1': '₹0.5 = ரூபாயின் 5 பத்தில் ஒன்றுகள்.',
  'mistake.U1.s2': '₹0.45 என்றால் 4 பத்தில் ஒன்றுகளும் 5 நூறில் ஒன்றுகளும்.',
  'mistake.U1.s3': '45 > 5, அதனால் ₹0.45 அதிகம்.',
  'mistake.U1.s4': '₹0.45 மிட்டாய் விலை அதிகம்.',
  'mistake.U1.fine1': 'சரி: 5 பட்டை 10 பைசா.',
  'mistake.U1.fine2': 'சரி: 4 பட்டை + 5 பைசா.',
  'mistake.U1.fine4': 'இந்த வரி முந்தையதை மட்டும் சொல்கிறது. முன்னால் பார்.',
  'mistake.U1.found': 'இங்கே. நேகா 45-ஐ 5-உடன் ஒப்பிட்டாள்; ஆனால் ₹0.5 = 50 பைசா. இடம் வாரியாக: 5 பத்தில் ஒன்றுகள் > 4 பத்தில் ஒன்றுகள்.',
  'explain.U1.s': 'புள்ளிக்குப் பிறகு முதல் இலக்கம் ரூபாயின் {0}. ₹0.5 = {1} பைசா.',
  'explain.U1.tenths': 'பத்தில் ஒன்று', 'explain.U1.hundredths': 'நூறில் ஒன்று', 'explain.U1.ones': 'ஒன்றுகள்',
  'explain.U1.p5': '5', 'explain.U1.p50': '50', 'explain.U1.p500': '500',
  'explain.U1.hint': 'கட்டத்தைப் பார்: ஒரு பட்டை எவ்வளவு? ₹0.5-க்கு எத்தனை பட்டை?',
  'know.U1': 'புள்ளிக்குப் பிறகு ஒவ்வொரு இடமும் இடதில் உள்ளதின் பத்தில் ஒன்று; ரூபாய், பைசா படித்தல், மாற்றம், ஒப்பீடு.'
});
